#
# [3505] Minimum Operations to Make Elements Within K Subarrays Equal
#

# @lc code=start
import bisect
from collections import defaultdict, deque
import heapq
import statistics
from typing import List


class Solution:
    def add(self, x):
        if self.left_cnt >= self.right_cnt:
            heapq.heappush_max(self.left, x)
            self.left_sum += x

            remove = heapq.heappop_max(self.left)            
            heapq.heappush(self.right, remove)
            self.left_sum -= remove
            self.right_sum += remove
            self.right_cnt += 1

        else:
            heapq.heappush(self.right, x)
            self.right_sum += x

            remove = heapq.heappop(self.right)                
            heapq.heappush_max(self.left, remove)
            self.right_sum -= remove
            self.left_sum += remove
            self.left_cnt += 1

    def remove(self, x):
        self.delayed[x] += 1
        if self.left and x <= self.left[0]:
            self.left_cnt -= 1
            self.left_sum -= x
    
        else:
            self.right_cnt -= 1
            self.right_sum -= x

        self.rebalance()
        self.prune()
        
    
    def prune(self):
        while self.left and self.delayed[self.left[0]] > 0:
            x = heapq.heappop_max(self.left)
            self.delayed[x] -= 1

        while self.right and self.delayed[self.right[0]] > 0:
            x = heapq.heappop(self.right)
            self.delayed[x] -= 1

    def rebalance(self):        
        while self.left_cnt > self.right_cnt:
            r = heapq.heappop_max(self.left)
            heapq.heappush(self.right, r)
            self.right_cnt += 1
            self.right_sum += r
            self.left_cnt -= 1
            self.left_sum -= r

        while self.right_cnt > self.left_cnt + 1:
            r = heapq.heappop(self.right)
            heapq.heappush_max(self.left, r)
            self.left_cnt += 1
            self.left_sum += r
            self.right_cnt -= 1    
            self.right_sum -= r

    def getOper(self, even):

        if even:
            med = (self.left[0] + self.right[0]) / 2
        else:
            med = self.right[0]

        oper = (med * self.left_cnt - self.left_sum) + (self.right_sum - med * self.right_cnt)
        
        return oper
        
    def minOperations(self, nums: List[int], x: int, k: int) -> int:

        self.left = []
        self.right = []
        self.left_sum = 0
        self.right_sum = 0
        self.left_cnt = 0
        self.right_cnt = 0       
        self.delayed = defaultdict(int)
        even = (x % 2 == 0)

        que = deque()            
        opers = []

        for i, n in enumerate(nums):            
            if i == 0:
                que.append(n)                
                self.right.append(n)
                self.right_cnt += 1
                self.right_sum += n

            else:
                self.add(n)
                que.append(n)

            if i >= x:
                r = que.popleft()
                self.remove(r)                                            

            if i >= x-1:
                oper = self.getOper(even)
                opers.append(oper)

                       
        # print(opers)            

        dp = [[opers[0]]]
        for i in range(1, len(opers)):     
            o = opers[i]            

            cnt = (i // x) + 1
            if cnt > k:
                cnt = k

            curr_dp = []

            for j in range(cnt):
                if j == 0:                    
                    curr_dp.append(min(o, dp[-1][0])) 
                else:
                    alt = [o + dp[-x][j-1]]
                    if len(dp[-1]) >= j+1:
                        alt.append(dp[-1][j])

                    curr_dp.append(min(alt))
            
            dp.append(curr_dp)
                                  
            # print(dp, cnt)
                                    
        return int(dp[-1][-1])



        

        

        
        
